This Terraform configuration creates an AWS Elastic File System (EFS) with a lifecycle policy that automatically transitions files to Infrequent Access after 30 days. It also creates a basic VPC, two public subnets across different Availability Zones, a security group allowing NFS traffic, and EFS mount targets in each subnet.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Project name used for tagging resources."
  type        = string
  default     = "efs-lifecycle-demo"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_1" {
  description = "CIDR block for the first subnet."
  type        = string
  default     = "10.0.1.0/24"
}

